//
// Fixture tests for the JPEG 2000 (template 5.40) decoder subset.
//
// The fixtures in testdata/p7-3-j2k/ were produced on the Linux bench host by Jasper 4.2.9
// with --output-option "mode=int" (5/3 reversible, no quantization) from
// synthetic PGM fields generated by a documented LCG. The generator is
// reimplemented here byte for byte; its output is checked against the recorded
// SHA-256 of the original PGM files, so the expected samples are anchored to
// the corpus rather than to this test.
//
// Ground truth rule: the J2K image holds what the encoder read from the PGM,
// and a PGM reader takes one byte per sample when maxval <= 255 and two
// otherwise. f05 (maxval 255) therefore decodes to the byte stream, not to the
// 16-bit values written in the file.

package pack

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"testing"
)

type jpcFixture struct {
	name   string // file stem under testdata/p7-3-j2k
	gen    string // which synthetic field the codestream carries
	w, h   int
	bits   int
	maxval int
	seed   int
	pgmSHA string
	j2kSHA string
}

