// pgmBytes reproduces the generator: the field is written as big-endian 16-bit
// samples regardless of maxval, and f07 is the constant field.
func (f jpcFixture) pgmBytes() []byte {
	out := []byte(fmt.Sprintf("P5\n%d %d\n%d\n", f.w, f.h, f.maxval))
	st := uint32(f.seed)
	for j := 0; j < f.h; j++ {
		for i := 0; i < f.w; i++ {
			v := uint32(0)
			if f.gen == "f07" {
				v = 777
			} else {
				st = 1103515245*st + 12345
				base := uint32(i*37+j*61) % uint32(f.maxval)
				v = (base + (st >> 16)) % uint32(f.maxval)
			}
			out = append(out, byte(v>>8), byte(v))
		}
	}
	return out
}

// expectedSamples is what the encoder stored in the codestream: the PGM data
// read with the sample width a PGM reader uses for this maxval.
func (f jpcFixture) expectedSamples() []int32 {
	data := f.pgmBytes()
	data = data[len(fmt.Sprintf("P5\n%d %d\n%d\n", f.w, f.h, f.maxval)):]
	width := 2
	if f.maxval <= 255 {
		width = 1
	}
	out := make([]int32, f.w*f.h)
	for i := range out {
		if width == 2 {
			out[i] = int32(data[2*i])<<8 | int32(data[2*i+1])
		} else {
			out[i] = int32(data[i])
		}
	}
	return out
}

func TestJPCFixtureDecodeBitExact(t *testing.T) {
	dir := filepath.Join("..", "testdata", "p7-3-j2k")
	for _, f := range jpcFixtures {
		f := f
		t.Run(f.name, func(t *testing.T) {
			path := filepath.Join(dir, f.name+".j2k")
			data, err := os.ReadFile(path)
			if err != nil {
				t.Skipf("fixture %s absent: %v", path, err)
			}
			if got := sha256.Sum256(data); hex.EncodeToString(got[:]) != f.j2kSHA {
				t.Fatalf("%s: SHA-256 mismatch: got %s want %s", f.name, hex.EncodeToString(got[:]), f.j2kSHA)
			}
			if got := sha256.Sum256(f.pgmBytes()); hex.EncodeToString(got[:]) != f.pgmSHA {
				t.Fatalf("%s: generator does not reproduce the source PGM: got %s want %s", f.name, hex.EncodeToString(got[:]), f.pgmSHA)
			}

			samples, w, h, prec, err := jpcDecodeSamples(data)
			if err != nil {
				t.Fatalf("%s: decode failed: %v", f.name, err)
			}
			if w != f.w || h != f.h {
				t.Fatalf("%s: image %dx%d, want %dx%d", f.name, w, h, f.w, f.h)
			}
			if prec != f.bits {
				t.Errorf("%s: component precision %d, want %d", f.name, prec, f.bits)
			}
			want := f.expectedSamples()
			if len(samples) != len(want) {
				t.Fatalf("%s: %d samples, want %d", f.name, len(samples), len(want))
			}
			for i := range want {
				if samples[i] != want[i] {
					t.Fatalf("%s: sample %d (row %d col %d) = %d, want %d",
						f.name, i, i/f.w, i%f.w, samples[i], want[i])
				}
			}
		})
	}
}

// TestJPCRejectsUnsupportedFeatures checks the fail-loud contract: a codestream
// outside the implemented subset must return an explicit error, never a guess.
// The marker segments are located by scanning rather than by assuming offsets.
func TestJPCRejectsUnsupportedFeatures(t *testing.T) {
	data, err := os.ReadFile(filepath.Join("..", "testdata", "p7-3-j2k", "f01.j2k"))
	if err != nil {
		t.Skipf("fixture absent: %v", err)
	}
	codOff := -1
	for i := 0; i+2 < len(data); i++ {
		if data[i] == 0xff && data[i+1] == 0x52 {
			codOff = i
			break
		}
	}
	if codOff < 0 {
		t.Fatal("COD marker not found in fixture")
	}

	t.Run("irreversible 9/7", func(t *testing.T) {
		out := append([]byte(nil), data...)
		out[codOff+4+9] = 0 // Scod parameters byte 9: Transform = 0
		_, _, _, _, err := jpcDecodeSamples(out)
		var uns *ErrJPCUnsupported
		if err == nil || !asUnsupported(err, &uns) {
			t.Fatalf("err = %v, want ErrJPCUnsupported", err)
		}
	})
	t.Run("precincts declared without precinct bytes", func(t *testing.T) {
		out := append([]byte(nil), data...)
		out[codOff+4] |= 0x01 // Scod bit 0: precincts used, but no precinct bytes follow
		_, _, _, _, err := jpcDecodeSamples(out)
		var mal *ErrJPCMalformed
		if err == nil || !errors.As(err, &mal) {
			t.Fatalf("err = %v, want ErrJPCMalformed for a COD that declares precincts but carries no precinct bytes", err)
		}
	})
	t.Run("quantized QCD", func(t *testing.T) {
		out := append([]byte(nil), data...)
		for i := 0; i+2 < len(out); i++ {
			if out[i] == 0xff && out[i+1] == 0x5c {
				out[i+4] = 0x21 // Sqcd: style 1 (derivation)
				break
			}
		}
		_, _, _, _, err := jpcDecodeSamples(out)
		var uns *ErrJPCUnsupported
		if err == nil || !asUnsupported(err, &uns) {
			t.Fatalf("err = %v, want ErrJPCUnsupported", err)
		}
	})
	t.Run("Psot = 0", func(t *testing.T) {
		out := append([]byte(nil), data...)
		sot := -1
		for i := 0; i+2 < len(out); i++ {
			if out[i] == 0xff && out[i+1] == 0x90 {
				sot = i
				break
			}
		}
		if sot < 0 {
			t.Fatal("SOT marker not found in fixture")
		}
		// SOT payload: tileno(2) Psot(4) partno(1) numparts(1) at offset +4.
		for j := sot + 6; j < sot+10; j++ {
			out[j] = 0
		}
		var uns *ErrJPCUnsupported
		if _, _, _, _, err := jpcDecodeSamples(out); err == nil || !asUnsupported(err, &uns) {
			t.Fatalf("err = %v, want ErrJPCUnsupported for a tile-part with no declared length", err)
		}
	})
	t.Run("SOT declares numparts = 0", func(t *testing.T) {
		out := append([]byte(nil), data...)
		sot := -1
		for i := 0; i+2 < len(out); i++ {
			if out[i] == 0xff && out[i+1] == 0x90 {
				sot = i
				break
			}
		}
		if sot < 0 {
			t.Fatal("SOT marker not found in fixture")
		}
		out[sot+11] = 0 // numparts: partno 0 is not below 0 parts
		var mal *ErrJPCMalformed
		if _, _, _, _, err := jpcDecodeSamples(out); err == nil || !errors.As(err, &mal) {
			t.Fatalf("err = %v, want ErrJPCMalformed for an inconsistent part count", err)
		}
	})
	t.Run("truncated tile data", func(t *testing.T) {
		out := append([]byte(nil), data...)
		out = out[:len(out)-40]
		if _, _, _, _, err := jpcDecodeSamples(out); err == nil {
			t.Fatal("expected an error for truncated tile data")
		}
	})
	t.Run("unknown marker", func(t *testing.T) {
		out := append([]byte(nil), data...)
		// Insert a RGN marker segment right before SOD.
		for i := 0; i+2 < len(out); i++ {
			if out[i] == 0xff && out[i+1] == 0x93 {
				seg := []byte{0xff, 0x5e, 0x00, 0x05, 0x00, 0x00, 0x00}
				out = append(out[:i], append(seg, out[i:]...)...)
				break
			}
		}
		var uns *ErrJPCUnsupported
		if _, _, _, _, err := jpcDecodeSamples(out); err == nil || !asUnsupported(err, &uns) {
			t.Fatalf("err = %v, want ErrJPCUnsupported", err)
		}
	})
}

func asUnsupported(err error, target **ErrJPCUnsupported) bool {
	uns, ok := err.(*ErrJPCUnsupported)
	if ok {
		*target = uns
	}
	return ok
}
